import { readFileSync, writeFileSync } from "node:fs";
test("completion queue preserves the original 10s waiting deadline", async () => {
  const path = "tests/fleet-connector-install.test.mjs", target = "fifty cross-process rotations stay exclusive and recover an actually killed owner";
  const original = readFileSync(path, "utf8");
  const begin = original.indexOf('"'"'test("'"'"' + target), end = original.indexOf("\ntest(", begin + 1);
  assert.ok(begin >= 0 && end > begin, "the real stress body must exist");
  const body = original.slice(begin, end);
  assert.equal(body.split("setTimeout(done, 100)").length - 1, 1, "exactly the original holder delay must change");
  let child, timer, output = "", result;
  try {
    writeFileSync(path, original.slice(0, begin) + body.replace("setTimeout(done, 100)", "setTimeout(done, 11000)") + original.slice(end));
    child = spawn(process.execPath, ["scripts/run-tests-with-quarantine.mjs", "--import", "tsx", "--test",
      "--test-name-pattern=" + target, path], { stdio: ["ignore", "pipe", "pipe"] });
    child.stdout.on("data", bytes => { output += bytes; });
    child.stderr.on("data", bytes => { output += bytes; });
    result = await new Promise((resolve, reject) => {
      child.once("error", reject);
      child.once("close", (code, signal) => resolve({ code, signal }));
      timer = setTimeout(() => child.kill("SIGKILL"), 120_000);
    });
  } finally {
    clearTimeout(timer);
    writeFileSync(path, original);
  }
  assert.equal(result.signal, null, "the real stress body must complete, not time out");
  assert.equal(result.code, 1, "slow owner must be refused by the original 10s waiting deadline");
